import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
from decimal import Decimal,ROUND_HALF_UP
B="http://localhost:8080";tok=None;notes=[]
def gettok():
    global tok
    while True:
        try:
            r=urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST",data=b""));tok=json.load(r)["token"];return
        except urllib.error.HTTPError as e:
            time.sleep(float(e.headers.get("Retry-After") or 1))
def get(p):
    for a in range(200):
        if tok is None: gettok()
        try:
            return json.load(urllib.request.urlopen(urllib.request.Request(B+p,headers={"Authorization":"Bearer "+tok}),timeout=30))
        except urllib.error.HTTPError as e:
            if e.code==404: return None
            if e.code==401: gettok(); continue
            if e.code==429: time.sleep(float(e.headers.get("Retry-After") or 1)); continue
            notes.append((p,e.code)); time.sleep(0.5)
        except Exception as e: notes.append((p,str(e))); time.sleep(0.5)
    raise SystemExit("fail "+p)
seen={};dups=0;p="/orders?page=1";pages=0
while p:
    d=get(p);pages+=1
    for o in d["items"]:
        if o["id"] in seen: dups+=1
        else: seen[o["id"]]=o
    p=d["next"]
print("pages",pages,d["total_pages"],"orders",len(seen),"dups",dups)
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={k:0 for k in["north","south","east","west"]};n=0;st=set();naive=0
for o in seen.values():
    st.add(o["status"])
    if o["status"]!="shipped":continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: naive+=1;t=t.replace(tzinfo=timezone.utc)
    t=t.astimezone(timezone.utc)
    if not(lo<=t<hi):continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
    C=cust[c]
    if C is None: print("missing cust",o);continue
    v=(Decimal(o["amount_cents"])*(100-C["discount_pct"])/100).quantize(Decimal(1),ROUND_HALF_UP)
    reg[C["region"]]+=int(v);n+=1
print("statuses",st,"naive",naive,"notes",notes[:10],len(notes))
r={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg}
json.dump(r,open("/workspace/result.json","w"),indent=2);print(r)
EOF
